// Jour Tempo: today's and tomorrow's Tempo colour, never guessed.
// Input: answer of the "http request" node, or an error caught by the "catch" node.
// Output 1: usable colours. Output 2: colours unknown (no data, error or expired data).
const ATTRIBUTION = "Couleurs Tempo : RTE, via Jour Tempo (https://jourtempo.fr)";
const CODES = ["bleu", "blanc", "rouge"];

function valid(d) {
    return d && typeof d === "object" && d.aujourdhui && d.demain &&
        CODES.includes(d.aujourdhui.code) && typeof d.perime_apres === "string" &&
        !isNaN(Date.parse(d.perime_apres));
}

// Tempo day (06:00 to 06:00, Paris time) at a given instant, as "YYYY-MM-DD".
function tempoDay(ms) {
    return new Intl.DateTimeFormat("en-CA", {
        timeZone: "Europe/Paris", year: "numeric", month: "2-digit", day: "2-digit"
    }).format(new Date(ms - 6 * 3600 * 1000));
}

let problem = null;
if (msg.error) {
    problem = "request failed: " + (msg.error.message || msg.error);
} else if (msg.statusCode !== 200) {
    problem = "HTTP " + msg.statusCode;
} else if (!valid(msg.payload)) {
    problem = "invalid data";
} else {
    flow.set("jourtempo_last", msg.payload);   // keep the last good answer
}

const data = flow.get("jourtempo_last");
const now = Date.now();
let today = "inconnu", tomorrow = "inconnu";
if (data && now < Date.parse(data.perime_apres)) {
    const day = tempoDay(now);
    if (day === data.aujourdhui.date) {
        today = data.aujourdhui.code;
        tomorrow = CODES.includes(data.demain.code) ? data.demain.code : "inconnu";
    } else if (day === data.demain.date && CODES.includes(data.demain.code)) {
        today = data.demain.code;            // after 06:00 the announced "tomorrow" is today
    }
}

if (today === "inconnu") {
    const reason = problem || (data ? "data expired since " + data.perime_apres : "no data yet");
    node.status({ fill: "grey", shape: "ring", text: "unknown: " + reason });
    msg.payload = { today: "inconnu", tomorrow: "inconnu", error: reason };
    return [null, msg];
}

const c = (data.saison && data.saison.compteurs) || {};
const left = (k) => (c[k] && typeof c[k].restants === "number") ? c[k].restants : null;
msg.payload = {
    today: today,
    tomorrow: tomorrow,
    today_date: data.aujourdhui.date,
    tomorrow_date: data.demain.date,
    remaining: { bleu: left("bleu"), blanc: left("blanc"), rouge: left("rouge") },
    expires: data.perime_apres,
    collected: data.collecte_le,
    from_cache: problem !== null,
    warning: problem,
    attribution: ATTRIBUTION
};
const fill = { bleu: "blue", blanc: "grey", rouge: "red" }[today];
node.status({ fill: fill, shape: problem ? "ring" : "dot", text: "today " + today + ", tomorrow " + tomorrow });
return [msg, null];
